/**
 * Writes the keyframes of the guide bot's first-visit flight into src/styles.css,
 * between the "bot-flight:start" and "bot-flight:end" markers.
 *
 *   node scripts/bot-path.mjs && pnpm format
 *
 * The path is one smooth curve (a Catmull-Rom spline) through WAYPOINTS, walked at an
 * even speed that eases in and out, and sampled into enough keyframes that the straight
 * pieces between them cannot be seen. To change the flight, edit WAYPOINTS and run this
 * again; do not edit the keyframes by hand.
 */
import { readFile, writeFile } from 'node:fs/promises';
import { fromRoot } from './lib.mjs';

/**
 * Where the bot's head is, as an offset from its landing spot in the corner:
 * [vw to the left (negative), vh upward (negative)].
 */
const WAYPOINTS = [
  [-26, -52], // out of the hero's sphere
  [-40, -65],
  [-57, -61], // over the heading
  [-66, -46],
  [-60, -31],
  [-44, -25], // bottom of the loop, now heading right
  [-27, -31],
  [-13, -35], // a long, shallow arc toward the right edge
  [-4, -24],
  [0, 0], // lands in the ring
];
const STEPS = 48;
/** Largest size in flight, as a multiple of the size at rest. */
const MAX_SCALE = 2.1;
/** Largest lean into a turn, in degrees. */
const MAX_BANK = 16;
/** A typical window is wider than tall: weigh vw against vh when measuring distance. */
const ASPECT = 1.6;

const smoothstep = (t) => t * t * (3 - 2 * t);
const clamp01 = (t) => Math.min(1, Math.max(0, t));

/** Uniform Catmull-Rom through the waypoints; the ends repeat so the curve reaches them. */
function pointAt(u) {
  const last = WAYPOINTS.length - 1;
  const at = Math.min(Math.floor(u * last), last - 1);
  const t = u * last - at;
  const p = (i) => WAYPOINTS[Math.min(last, Math.max(0, i))];
  // One extra point past the end keeps the bot moving down into the corner as it arrives.
  const p3 = at + 2 > last ? [p(last)[0] + 1, p(last)[1] + 14] : p(at + 2);
  const [p0, p1, p2] = [p(at - 1), p(at), p(at + 1)];
  return [0, 1].map(
    (k) =>
      0.5 *
      (2 * p1[k] +
        (-p0[k] + p2[k]) * t +
        (2 * p0[k] - 5 * p1[k] + 4 * p2[k] - p3[k]) * t * t +
        (-p0[k] + 3 * p1[k] - 3 * p2[k] + p3[k]) * t * t * t),
  );
}

// Walk the curve finely once, so that positions can be looked up by distance travelled.
const FINE = 4000;
const fine = Array.from({ length: FINE + 1 }, (_, i) => pointAt(i / FINE));
const travelled = [0];
for (let i = 1; i <= FINE; i += 1) {
  const dx = (fine[i][0] - fine[i - 1][0]) * ASPECT;
  const dy = fine[i][1] - fine[i - 1][1];
  travelled.push(travelled[i - 1] + Math.hypot(dx, dy));
}
const total = travelled[FINE];
function atDistance(fraction) {
  const target = fraction * total;
  let i = travelled.findIndex((d) => d >= target);
  if (i < 0) i = FINE;
  return fine[i];
}

/** Even speed in the middle, a gentle start and a gentle landing. */
const progress = (t) => t + (smoothstep(t) - t) * 0.8;

function scaleAt(t) {
  if (t < 0.12) return MAX_SCALE * (1 - (1 - t / 0.12) ** 3);
  if (t < 0.5) return MAX_SCALE;
  return MAX_SCALE - (MAX_SCALE - 1) * smoothstep((t - 0.5) / 0.5);
}

const frames = [];
for (let i = 0; i <= STEPS; i += 1) {
  const t = i / STEPS;
  const [x, y] = atDistance(progress(t));
  // Lean in the direction of travel, and straighten up over the last fifth of the flight.
  const [ax] = atDistance(progress(clamp01(t - 0.03)));
  const [bx] = atDistance(progress(clamp01(t + 0.03)));
  const heading = Math.max(-1, Math.min(1, (bx - ax) / 6));
  const bank = MAX_BANK * heading * (1 - smoothstep(clamp01((t - 0.8) / 0.2)));
  const percent = Number((t * 100).toFixed(2));
  const transform =
    i === STEPS
      ? 'translate(0, 0) rotate(0deg) scale(1)'
      : `translate(${x.toFixed(2)}vw, ${y.toFixed(2)}vh) rotate(${bank.toFixed(1)}deg) scale(${scaleAt(t).toFixed(3)})`;
  frames.push(`  ${percent}% {\n    transform: ${transform};\n  }`);
}
const block = `@keyframes bot-flight {\n${frames.join('\n')}\n}`;

const START = '/* bot-flight:start (generated by scripts/bot-path.mjs) */';
const END = '/* bot-flight:end */';
const cssPath = fromRoot('src/styles.css');
const css = await readFile(cssPath, 'utf8');
const from = css.indexOf(START);
const to = css.indexOf(END);
if (from < 0 || to < from) {
  console.error('src/styles.css is missing the bot-flight markers.');
  process.exit(1);
}
await writeFile(cssPath, `${css.slice(0, from)}${START}\n${block}\n${css.slice(to)}`);
console.log(`bot-flight: ${frames.length} keyframes written to src/styles.css`);
